const dateLabel=v=>{try{return new Date(v).toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',timeZone:'America/Denver'})}catch{return v||'TBD'}};
const timeLabel=v=>{try{return new Date(v).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/Denver'})}catch{return''}};
const icons={today:'M4 5h16v15H4zM8 3v4m8-4v4M4 10h16',schedule:'M4 5h16v15H4zM8 3v4m8-4v4M4 10h16M8 14h3m2 0h3',pipeline:'M4 6h4v12H4zm6 3h4v9h-4zm6-5h4v14h-4z',walkthroughs:'M4 4h16v16H4zM8 2v4m8-4v4M7 11h4m-4 4h7',delivery:'M3 6h12v11H3zm12 4h4l2 3v4h-6M7 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm11 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z',scorecard:'M4 19V9m5 10V5m5 14v-7m5 7V3',proof:'M4 5h4l2-2h4l2 2h4v15H4zM12 9a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',playbook:'M5 4h11a3 3 0 0 1 3 3v13H8a3 3 0 0 1-3-3zm0 0v13a3 3 0 0 0 3 3',settings:'M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Zm0-12v2m0 13v2m8.5-8.5h-2m-13 0h-2m14.5-6-1.5 1.5m-9 9L6 18m12 0-1.5-1.5m-9-9L6 6',external:'M14 4h6v6m0-6-9 9M10 6H4v14h14v-6'};
const svg=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.today}"/></svg>`;
const nav=[['RUN THE DAY','today','Today'],['RUN THE DAY','schedule','Schedule'],['RUN THE DAY','open_shifts','Open shifts'],['RUN THE DAY','availability','My availability'],['RUN THE DAY','timesheets','Timesheets'],['RUN THE DAY','walkthroughs','Walkthroughs'],['RUN THE DAY','delivery','Job delivery'],['CLIENT WORK','customers','Customers'],['CLIENT WORK','finance','Estimates & payments'],['CRM','pipeline','New HighLevel leads'],['GROW THE ENGINE','scorecard','Scorecard'],['GROW THE ENGINE','proof','Proof library'],['GROW THE ENGINE','playbook','EGC playbook'],['SYSTEM','settings','Integrations']];

function install(){const dash=$('#dashboard');if(!dash||dash.classList.contains('ops-installed'))return;dash.classList.add('ops-installed');let group='';const shell=document.createElement('div');shell.className='ops-shell';shell.innerHTML=`<aside class="ops-rail" id="ops-rail"><div class="ops-brand"><span class="ops-brand-mark">EGC</span><span><strong>Field Command</strong><small>RUN THE PROMISE</small></span></div><nav class="ops-nav" aria-label="Employee hub">${nav.map(n=>{const h=n[0]!==group?`<div class="ops-nav-label">${group=n[0]}</div>`:'';return h+`<button data-ops-tab="${n[1]}" onclick="opsGo('${n[1]}')">${svg(n[1])}<span>${n[2]}</span></button>`}).join('')}</nav><div class="ops-rail-foot"><a href="https://app.gohighlevel.com/" target="_blank" rel="noopener">${svg('external')}<span>Open HighLevel<small>CRM · conversations · automation</small></span></a><a href="/crew/">${svg('delivery')}<span>Open crew tools<small>Field execution</small></span></a></div></aside><section class="ops-workspace"><header class="ops-topbar"><button class="ops-menu" type="button" aria-label="Open menu" onclick="document.getElementById('ops-rail').classList.toggle('open')">${svg('playbook')}</button><div class="ops-context"><span id="ops-kicker">RUN THE DAY</span><strong id="ops-title">Today</strong></div><div class="ops-system"><span id="ops-sync-dot"></span><span id="ops-sync-label">Checking HighLevel</span><button onclick="opsRefresh()">Refresh</button></div></header><main id="ops-main" class="ops-main"></main></section>`;dash.appendChild(shell);document.addEventListener('click',e=>{if(innerWidth<=860&&!e.target.closest('.ops-rail')&&!e.target.closest('.ops-menu'))$('#ops-rail')?.classList.remove('open')});S.installed=true;loadAll();S.ghlTimer=setInterval(()=>{if(!document.hidden)loadGhl()},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadGhl()});go('today')}
const head=(k,t,c,a='')=>`<div class="ops-page-head"><div><span class="ops-eyebrow">${esc(k)}</span><h1>${esc(t)}</h1><p>${esc(c)}</p></div><div class="ops-page-actions">${a}</div></div>`;
const action=(l,h,s='')=>`<a class="ops-button ${s}" href="${h}">${l}</a>`;
const badge=(t,s='')=>`<span class="ops-status ${s}">${esc(t||'—')}</span>`;
const empty=(t,c,a='')=>`<div class="ops-empty"><span>EGC</span><h3>${esc(t)}</h3><p>${esc(c)}</p>${a}</div>`;
const scheduleLockId=date=>`_egc_schedule_lock_${String(date||'').replace(/[^0-9-]/g,'')}`;
const isScheduleLock=j=>j?.recordType==='schedule_lock'||String(j?.id||'').startsWith('_egc_schedule_lock_');
const scheduleLockRef=(store,date)=>store.collection('jobs').doc(scheduleLockId(date));
const isAvailability=j=>j?.recordType==='crew_availability'||j?.type==='availability';
const jobs=()=>typeof jobsCache==='undefined'?[]:jobsCache.filter(j=>!isScheduleLock(j)&&!isAvailability(j));
const availabilityRows=()=>typeof jobsCache==='undefined'?[]:jobsCache.filter(isAvailability);
const jobStage=j=>typeof getPipelineStatus==='function'?getPipelineStatus(j):(j.pipelineStatus||j.status||'scheduled');
const isToday=v=>Boolean(v)&&String(v).slice(0,10)===day();
const todayJobs=()=>jobs().filter(j=>isToday(j.date||j.startTime)&&j.type!=='blocked');
const todayWalkthroughs=()=>todayJobs().filter(j=>j.type==='walkthrough');
const todayDelivery=()=>todayJobs().filter(j=>j.type!=='walkthrough');
const openJobs=()=>jobs().filter(j=>j.type!=='walkthrough'&&j.type!=='blocked'&&!terminalScheduleStages.includes(jobStage(j)));
const hasCrewBrief=j=>Boolean(j?.jobInstructions&&(j.jobInstructions.customerGoal||j.jobInstructions.keepItems||j.jobInstructions.removeItems||j.jobInstructions.customerNotes)||(j?.notes||j?.scope||j?.walkthroughNotes));
const clientCheckCount=(j,key)=>Array.isArray(j?.clientChecklists?.[key])?j.clientChecklists[key].length:0;
const terminalScheduleStages=['cancelled','completed','invoiced','paid','review_requested','closed'];
const activeScheduleJob=j=>j&&!terminalScheduleStages.includes(jobStage(j));
const minutes=v=>{const m=String(v||'').match(/^(\d{1,2}):(\d{2})/);return m?Number(m[1])*60+Number(m[2]):NaN};
const overlaps=(aStart,aEnd,bStart,bEnd)=>Number.isFinite(aStart)&&Number.isFinite(aEnd)&&Number.isFinite(bStart)&&Number.isFinite(bEnd)&&aStart<bEnd&&bStart<aEnd;
function collisionFor(candidate,excludeId=''){const start=minutes(candidate.time),end=minutes(candidate.endTime);return jobs().find(j=>j.id!==excludeId&&activeScheduleJob(j)&&String(j.date||'').slice(0,10)===candidate.date&&overlaps(start,end,minutes(j.time||String(j.startTime||'').slice(11,16)),minutes(j.endTime||String(j.endTime||'').slice(11,16))))||null}
function collisionMessage(j){return `${j.customer||j.title||j.serviceType||'Existing work'} is already scheduled ${eventTime(j)}–${j.endTime||'later'}. Choose a different time.`}
function lockEntry(job){return{id:job.id,start:job.time,end:job.endTime,label:job.customer||job.serviceType||'Scheduled work',status:job.status||'scheduled',updatedAt:job.updatedAt||new Date().toISOString()}}
async function saveScheduledJob(job,previous={}){
  const local=collisionFor(job,job.id);if(local){const e=new Error(collisionMessage(local));e.code='SCHEDULE_CONFLICT';throw e}
  const ref=db.collection('jobs').doc(job.id),newLock=scheduleLockRef(db,job.date),oldDate=previous.date&&previous.date!==job.date?previous.date:'',customerUpdate=job.customerId&&job.internalNotes?{latestJobId:job.id,operationalNotes:job.internalNotes||'',internalNotes:job.internalNotes||'',latestJobInstructions:job.jobInstructions||{},latestClientChecklists:job.clientChecklists||{},updatedAt:job.updatedAt}:null,customerRef=customerUpdate?db.collection('customers').doc(job.customerId):null;
  if(typeof db.runTransaction!=='function'){await ref.set(job,{merge:true});if(customerRef)await customerRef.set(customerUpdate,{merge:true});return}
  await db.runTransaction(async tx=>{
    const newSnap=await tx.get(newLock);let entries=Array.isArray(newSnap.data()?.entries)?newSnap.data().entries:[];
    let oldLock=null,oldEntries=[];if(oldDate){oldLock=scheduleLockRef(db,oldDate);const oldSnap=await tx.get(oldLock);oldEntries=Array.isArray(oldSnap.data()?.entries)?oldSnap.data().entries:[]}
    entries=entries.filter(x=>x.id!==job.id&&activeScheduleJob(x));
    const conflict=entries.find(x=>overlaps(minutes(job.time),minutes(job.endTime),minutes(x.start),minutes(x.end)));
    if(conflict){const e=new Error(collisionMessage({customer:conflict.label,time:conflict.start,endTime:conflict.end}));e.code='SCHEDULE_CONFLICT';throw e}
    tx.set(newLock,{recordType:'schedule_lock',date:job.date,entries:[...entries,lockEntry(job)],updatedAt:job.updatedAt},{merge:true});
    if(oldLock)tx.set(oldLock,{recordType:'schedule_lock',date:oldDate,entries:oldEntries.filter(x=>x.id!==job.id),updatedAt:job.updatedAt},{merge:true});
    tx.set(ref,job,{merge:true});
    if(customerRef)tx.set(customerRef,customerUpdate,{merge:true});
  });
}
async function remoteCollision(candidate){
  if(candidate.type==='blocked'||S.ghl.error)return null;
  try{const start=new Date(`${candidate.date}T00:00`).toISOString(),end=new Date(`${candidate.date}T23:59`).toISOString(),r=await fetch(`/api/highlevel?view=schedule&start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`,{cache:'no-store'}),j=await r.json();if(!r.ok)return null;const a=minutes(candidate.time),b=minutes(candidate.endTime);return(j.events||[]).find(x=>x.id!==candidate.highlevelAppointmentId&&!['cancelled','completed'].includes(String(x.status||'').toLowerCase())&&String(x.startTime||'').slice(0,10)===candidate.date&&overlaps(a,b,minutes(String(x.startTime||'').slice(11,16)),minutes(String(x.endTime||'').slice(11,16))))||null}catch{return null}
}
const routeUrl=address=>`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(address||'')}`;
const employeeIdentity=()=>String(sessionStorage.getItem('egc_u')||localStorage.getItem('egc_u')||'').trim();
const personKey=value=>String(value||'').toLowerCase().replace(/[^a-z0-9]/g,'');
const sameEmployee=(a,b)=>{const x=personKey(a),y=personKey(b);return Boolean(x&&y&&(x===y||(Math.min(x.length,y.length)>=3&&(x.startsWith(y)||y.startsWith(x)))))};
const crewNames=j=>{const explicit=(Array.isArray(j.assignedCrew)?j.assignedCrew:[]).map(x=>typeof x==='string'?x:(x?.name||x?.id||'')).map(x=>String(x).trim()).filter(Boolean);if(explicit.length)return[...new Set(explicit)];return[...new Set(String(j.assignedTo||'').split(/\s*(?:,|\+|&|\band\b)\s*/i).map(x=>x.trim()).filter(Boolean))]};
const crewFromText=(text,fallback=[])=>{const parsed=String(text||'').split(/\s*(?:,|\+|&|\band\b)\s*/i).map(x=>x.trim()).filter(Boolean);return parsed.length?[...new Set(parsed)]:crewNames({assignedCrew:fallback})};
const pickupEnabled=j=>Boolean(j?.shiftPickupEnabled??j?.openShift);
const openShiftJobs=()=>jobs().filter(j=>j.type==='job'&&pickupEnabled(j)&&String(j.date||'')>=day()&&!['closed','completed','cancelled','paid','invoiced','review_requested'].includes(j.pipelineStatus||j.status||'scheduled')).sort((a,b)=>String(a.date+a.time).localeCompare(String(b.date+b.time)));
const activeAvailability=()=>availabilityRows().filter(x=>x.status!=='cancelled'&&String(x.date||'')>=day());
function crewAvailabilityConflict(date,start,end,names){return activeAvailability().find(a=>String(a.date||'')===String(date||'')&&names.some(n=>sameEmployee(n,a.employee))&&overlaps(minutes(start),minutes(end),minutes(a.time),minutes(a.endTime)))}
const unavailableFor=(job,employee)=>crewAvailabilityConflict(job?.date,job?.time,job?.endTime,[employee]);

async function loadAll(){await Promise.all([loadIntegrations(),loadGhl(),loadWalks()]);render();setTimeout(retryDueSyncs,1500)}
async function loadIntegrations(){try{const r=await fetch('/api/integration-status',{cache:'no-store'}),j=await r.json();if(r.ok)S.integrations={...(j.status||{}),firebase:Boolean(window.firebase)||(j.status||{}).firebase}}catch{S.integrations.firebase=Boolean(window.firebase)}}
async function loadGhl(){S.ghl.loading=true;S.ghl.error='';sync();try{const r=await fetch('/api/highlevel?view=command',{cache:'no-store'}),j=await r.json();if(!r.ok)throw new Error(j.code==='HIGHLEVEL_NOT_CONFIGURED'?'not-configured':j.error||'unavailable');S.ghl={loading:false,error:'',pipelines:j.pipelines||[],opportunities:j.opportunities||[],leadResetAt:j.leadResetAt||''}}catch(e){S.ghl.loading=false;S.ghl.error=e.message||'unavailable'}sync();render()}
async function loadWalks(){S.walks.loading=true;S.walks.error='';try{const r=await fetch('/api/highlevel?view=walkthroughs&date='+day(),{cache:'no-store'}),j=await r.json();if(!r.ok)throw new Error(j.code==='HIGHLEVEL_NOT_CONFIGURED'?'not-configured':j.error||'unavailable');S.walks={loading:false,error:'',events:(j.events||[]).filter(e=>isToday(e.startTime))}}catch(e){S.walks.loading=false;S.walks.error=e.message||'unavailable'}render()}
function sync(){const d=$('#ops-sync-dot'),l=$('#ops-sync-label');if(!d||!l)return;d.className=S.ghl.loading?'loading':S.ghl.error?'off':'on';l.textContent=S.ghl.loading?'Checking HighLevel':S.ghl.error==='not-configured'?'HighLevel key needed':S.ghl.error?'HighLevel unavailable':'HighLevel connected'}
function stageName(o){for(const p of S.ghl.pipelines){const s=(p.stages||[]).find(x=>x.id===o.pipelineStageId);if(s)return s.name||'Open'}return o.status||'Open'}
function go(name){S.active=name;all('[data-ops-tab]').forEach(b=>b.classList.toggle('active',b.dataset.opsTab===name));$('#ops-rail')?.classList.remove('open');const n=nav.find(x=>x[1]===name)||nav[0];if($('#ops-kicker'))$('#ops-kicker').textContent=n[0];if($('#ops-title'))$('#ops-title').textContent=n[2];render()}
window.opsGo=go;window.opsRefresh=loadAll;
function render(){const host=$('#ops-main');if(host&&views[S.active])host.innerHTML=views[S.active]()}
function notConfigured(what){return empty('HighLevel connection is the remaining blocker',`The ${what} is built and ready. Add a HighLevel private-integration token and location ID in Cloudflare to activate live data.`,`<button class="ops-button primary" onclick="opsGo('settings')">Show setup fields</button>`)}

function metrics(){const opp=S.ghl.opportunities,total=opp.reduce((a,o)=>a+Number(o.monetaryValue||0),0),deliveries=todayDelivery(),ready=deliveries.filter(j=>(j.notes||j.scope||j.walkthroughNotes)&&Number(j.priceQuoted||j.total||0)).length,reset=S.ghl.leadResetAt?new Date(S.ghl.leadResetAt).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'America/Denver'}):'the reset';return`<div class="ops-metrics"><article><span>New HighLevel leads</span><strong>${S.ghl.error?'—':opp.length}</strong><small>${S.ghl.error?'Connect CRM when the key is ready':`${money(total)} open value · since ${reset}`}</small></article><article><span>Walkthroughs today</span><strong>${todayWalkthroughs().length}</strong><small>Scheduled in the EGC Hub</small></article><article><span>Jobs today</span><strong>${deliveries.length}</strong><small>${ready} handoff-ready · ${deliveries.length-ready} need attention</small></article><article class="accent"><span>Target average ticket</span><strong>$1,400</strong><small>Win on contribution, not close rate alone</small></article></div>`}
function flywheel(){const rows=[['01','Lead response','HIGHLEVEL','Respond fast; sell the free walkthrough.'],['02','Walkthrough','FIELD','Diagnose pain, design outcome, lock scope and price.'],['03','Crew handoff','EGC HUB','Carry every promise, hazard, keep item and photo forward.'],['04','Reveal','FIELD','Final walkthrough, surprise gift, collect, ask for review.'],['05','Proof loop','GROWTH','Publish the transformation and feed the winning hook.']];return`<section class="ops-card ops-fly"><div class="ops-card-head"><div><span class="ops-eyebrow">THE OPERATING LOOP</span><h2>One promise, carried all the way through</h2></div>${badge('Walkthrough-first','info')}</div><div class="ops-fly-row">${rows.map(r=>`<article><b>${r[0]}</b><span>${r[2]}</span><h3>${r[1]}</h3><p>${r[3]}</p></article>`).join('')}</div></section>`}
function agenda(){const rows=todayJobs().map(x=>({...x,kind:x.type==='walkthrough'?'Walkthrough':'Job',at:x.date+'T'+(x.time||'08:00')})).sort((a,b)=>String(a.at).localeCompare(String(b.at)));if(!rows.length)return empty('Nothing scheduled today','Add a walkthrough, job, or blocked time in the Hub schedule.',`<button class="ops-button primary" onclick="opsOpenBooking()">Schedule work</button>`);return`<div class="ops-agenda">${rows.map(r=>`<article><time>${timeLabel(r.at)||'TBD'}</time><div><span>${r.kind} · ${esc(jobStage(r).replaceAll('_',' '))}</span><strong>${esc(r.customer||r.title||'Customer')}</strong><p>${esc(r.address||'Address not recorded')}</p></div><div class="ops-agenda-actions">${r.address?`<a href="${routeUrl(r.address)}" target="_blank" rel="noopener">Route</a>`:''}<a href="${r.kind==='Walkthrough'?`/crew/gameplan.html?walkthroughId=${encodeURIComponent(r.id)}`:`/crew/prejob.html?jobId=${encodeURIComponent(r.id)}`}">${r.kind==='Walkthrough'?'Start walkthrough':'Open crew brief'} →</a></div></article>`).join('')}</div>`}
function attention(){const x=[];if(S.ghl.error==='not-configured')x.push(['HighLevel is not connected','Add the API key and location ID in Cloudflare.','settings']);jobs().filter(j=>j.closeoutSyncStatus==='error').slice(0,3).forEach(j=>x.push([`${j.customer||'Job'} closeout needs HighLevel retry`,'The full closeout is safe in the Hub. Retry it from customer history.','customers']));jobs().filter(j=>Number(j.photoCount||j.jobInstructions?.photoCount||0)>0&&!j.photoDriveUrl&&['device_only','needs_setup','error'].includes(j.photoSyncStatus)).slice(0,3).forEach(j=>x.push([`${j.customer||'Job'} photos are not in Drive`,j.photoSyncStatus==='needs_setup'?'Connect Google Drive, then reopen and save the walkthrough on the original device.':'Reopen and save the walkthrough on the original device to retry the upload.','delivery']));openJobs().slice(0,5).forEach(j=>{if(!j.notes&&!j.scope&&!j.walkthroughNotes)x.push([`${j.customer||'Job'} has no crew brief`,'Carry the walkthrough promise into delivery.','delivery']);else if(!Number(j.priceQuoted||j.total||0))x.push([`${j.customer||'Job'} has no locked total`,'Confirm the flat rate before the crew rolls.','delivery'])});if(!x.length)x.push(['The handoff queue is clean','Review today’s appointments, then protect content capture.','walkthroughs']);return`<div class="ops-attention">${x.map(i=>`<button onclick="opsGo('${i[2]}')"><i></i><div><strong>${esc(i[0])}</strong><small>${esc(i[1])}</small></div><b>→</b></button>`).join('')}</div>`}

const isoDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function weekStart(value=S.weekAnchor){const d=value?new Date(value+'T12:00:00'):new Date(),shift=(d.getDay()+6)%7;d.setDate(d.getDate()-shift);d.setHours(12,0,0,0);return d}
function weekDays(){const start=weekStart();return Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return isoDate(d)})}
function eventTime(j){return j.time||String(j.startTime||'').slice(11,16)||'TBD'}
function syncState(j){if(j.type==='blocked')return badge('Hub only','info');const lifecycle=j.lifecycleSync?.status==='error'?`${badge('Workflow sync failed','warn')}<button class="ops-retry" type="button" onclick="event.stopPropagation();opsRetryLifecycle('${esc(j.id)}')">Retry</button>`:'';if(j.syncStatus==='synced')return badge('Synced','good')+lifecycle;if(j.syncStatus==='syncing')return badge('Syncing','info')+lifecycle;return `${badge(j.syncStatus==='error'?'Sync failed':'Sync pending',j.syncStatus==='error'?'warn':'info')}<button class="ops-retry" type="button" onclick="event.stopPropagation();opsRetrySync('${esc(j.id)}')">Retry</button>${lifecycle}`}
function photoState(j){const count=Number(j.photoCount||j.jobInstructions?.photoCount||0);if(!count)return'';const url=String(j.photoDriveUrl||''),safe=/^https:\/\/(?:drive|docs)\.google\.com\//i.test(url);if(safe)return`<a class="ops-photo-link" href="${esc(url)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${badge(`${count} photo${count===1?'':'s'} in Drive`,'good')}</a>`;if(j.photoSyncStatus==='needs_setup')return badge(`${count} photos · Drive setup needed`,'warn');if(j.photoSyncStatus==='error')return badge(`${count} photos · upload failed`,'warn');return badge(`${count} photos · original device`,'info')}
function scheduleGrid(){return`<div class="ops-week">${weekDays().map(date=>{const rows=jobs().filter(j=>String(j.date||j.startTime||'').slice(0,10)===date&&!['cancelled'].includes(jobStage(j))).sort((a,b)=>eventTime(a).localeCompare(eventTime(b)));const d=new Date(date+'T12:00:00');return`<section class="${date===day()?'today':''}"><header><span>${d.toLocaleDateString('en-US',{weekday:'short'})}</span><strong>${d.getDate()}</strong><button type="button" onclick="opsOpenBooking('${date}')" aria-label="Schedule on ${date}">+</button></header><div>${rows.length?rows.map(j=>`<article class="${esc(j.type||'job')}"><time>${esc(eventTime(j))}–${esc(j.endTime||'')}</time><strong>${esc(j.customer||j.title||j.serviceType||'Blocked time')}</strong><small>${esc(j.address||j.assignedTo||'')}</small><footer><span>${esc(j.type==='walkthrough'?'Walkthrough':j.type==='blocked'?'Blocked':j.recurrence&&j.recurrence!=='none'?'Recurring job':'Job')}</span>${activeScheduleJob(j)?`<button class="ops-edit-event" type="button" onclick="opsEditBooking('${esc(j.id)}')">Edit</button>`:`<b>${esc(jobStage(j).replaceAll('_',' '))}</b>`}${syncState(j)}</footer></article>`).join(''):`<button class="ops-day-empty" type="button" onclick="opsOpenBooking('${date}')">Add time</button>`}</div></section>`}).join('')}</div>`}
